import requests
def get_active_users(data):
    active = []
    for user in data['users']:
        if user.get('active', False):
            active.append(user['name'])
    return active

api_data = {
    'users': [
        {'name': 'John', 'active': True},
        {'name': 'Alice', 'active': False},
        {'name': 'Bob', 'active': True}
    ]
}

result = get_active_users(api_data)
print(result)

